import numpy as np
obs=np.array([16.2048,18.14,20.4428,27.8693,30.2243,32.756,34.4825,41.5814,45.1655,52.2565,53.6875])
d=1.5406/(2*np.sin(np.radians(obs/2)))
H=[];
for h in range(-4,5):
  for k in range(-4,5):
    for l in range(0,14):
      if (-h+k+l)%3 or (h==k==l==0): continue
      H.append((h*h+h*k+k*k,l*l))
H=np.array(H,float)
best=[]
for a in np.arange(5.0,8.5,0.005):
  A=4/3*H[:,0]/a**2
  for c in np.arange(12,21,0.02):
    ds=1/np.sqrt(A+H[:,1]/c**2)
    err=np.abs(ds[None,:]-d[:,None]).min(1).sum()
    best.append((err,a,c))
best.sort(); print(best[:8])
# cubic check
for a in np.arange(3.5,6.5,0.002):
  pass

